```java
import java.util.Scanner;

public class CharacterReplacer {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Prompt user to input a string
        System.out.print("Enter a string: ");
        String inputString = scanner.nextLine();

        // Prompt user to input the character to replace
        System.out.print("Enter the character to replace: ");
        char charToReplace = scanner.next().charAt(0);

        // Prompt user to input the replacement character
        System.out.print("Enter the replacement character: ");
        char replacementChar = scanner.next().charAt(0);

        // Replace all occurrences of the specified character
        String modifiedString = inputString.replace(charToReplace, replacementChar);

        // Print the modified string
        System.out.println("\nOriginal string: " + inputString);
        System.out.println("Modified string: " + modifiedString);

        // Optional: Count and display the number of replacements made
        int count = countOccurrences(inputString, charToReplace);
        System.out.println("Number of replacements: " + count);

        scanner.close();
    }

    // Helper method to count occurrences of a character in a string
    private static int countOccurrences(String str, char ch) {
        int count = 0;
        for (int i = 0; i < str.length(); i++) {
            if (str.charAt(i) == ch) {
                count++;
            }
        }
        return count;
    }
}
