Here's a comprehensive shell script that finds the sum of all numbers (integers and floats) in a tab-delimited file:

```bash
#!/bin/bash

# Script: sum_tabdelimited.sh
# Description: Calculates the sum of all numbers in a tab-delimited file
# Usage: ./sum_tabdelimited.sh <filename>

# Check if filename is provided
if [ $# -eq 0 ]; then
    echo "Usage: $0 <filename>"
    echo "Example: $0 data.txt"
    exit 1
fi

# Check if file exists
if [ ! -f "$1" ]; then
    echo "Error: File '$1' not found!"
    exit 1
fi

# Method 1: Using awk (recommended - handles both integers and floats)
echo "Calculating sum using awk..."
awk -F'\t' '
{
    for (i = 1; i <= NF; i++) {
        # Check if field is a number (integer or float)
        if ($i ~ /^-?[0-9]+\.?[0-9]*$/ || $i ~ /^-?[0-9]*\.[0-9]+$/) {
            sum += $i
        }
    }
}
END {
    printf "Total Sum: %.2f\n", sum
}' "$1"

