  // 1. It's a power of 2 (only one bit set)
  // 2. The single bit is at an even position (0, 2, 4, 6, etc.)

  // Check if it's a power of 2: num & (num - 1) should be 0
  const isPowerOfTwo = (num & (num - 1)) === 0;

  if (!isPowerOfTwo) {
